def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / np.maximum(bins, 1e-9)
    score = -10.0 * np.maximum(0.0, remaining) - 1.0 / (np.abs(fill_ratio - 0.6) + 1e-3)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / np.maximum(bins, 1e-9)
    score = -5.0 * (np.maximum(0.0, remaining) ** 2) - 1.0 / ((fill_ratio - 0.7) ** 2 + 1e-3)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = item / np.maximum(bins, 1e-9)
    score = -1.5 * np.abs(utilization - 0.5) - 0.1 * remaining
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = item / np.maximum(bins, 1e-9)
